create type public.application_stage as enum ('Not Started','Interested','Preparing','Submitted','Under Review','Approved','Rejected');
create type public.verification_status as enum ('unverified','verified','needs_review','rejected');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, institution text, course text, study_year smallint, location text, income_range text, category text, preferences jsonb not null default '{}'::jsonb, onboarding_complete boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.scholarships (id uuid primary key default gen_random_uuid(), title text not null, provider text not null, description text not null, amount numeric, currency text not null default 'INR', funding_type text, location text, category text, opening_date date, closing_date date, official_url text not null, source_url text, verification_status public.verification_status not null default 'unverified', last_verified_at timestamptz, is_demo boolean not null default false, created_at timestamptz not null default now());
create table public.eligibility_criteria (id uuid primary key default gen_random_uuid(), scholarship_id uuid not null references public.scholarships(id) on delete cascade, criterion_type text not null, operator text, value jsonb not null, explanation text);
create table public.scholarship_requirements (id uuid primary key default gen_random_uuid(), scholarship_id uuid not null references public.scholarships(id) on delete cascade, document_name text not null, required boolean not null default true);
create table public.saved_scholarships (user_id uuid references auth.users(id) on delete cascade, scholarship_id uuid references public.scholarships(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id, scholarship_id));
create table public.applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, scholarship_id uuid not null references public.scholarships(id) on delete cascade, stage public.application_stage not null default 'Not Started', submitted_at timestamptz, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, scholarship_id));
create table public.application_checklist_items (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, label text not null, completed boolean not null default false, sort_order smallint not null default 0);
create table public.documents (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, storage_path text not null unique, category text, expires_on date, verification_status public.verification_status not null default 'needs_review', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table public.reminders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, scholarship_id uuid references public.scholarships(id) on delete cascade, remind_at timestamptz not null, sent_at timestamptz);
create table public.administrators (user_id uuid primary key references auth.users(id) on delete cascade, granted_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.scholarships enable row level security; alter table public.eligibility_criteria enable row level security; alter table public.scholarship_requirements enable row level security; alter table public.saved_scholarships enable row level security; alter table public.applications enable row level security; alter table public.application_checklist_items enable row level security; alter table public.documents enable row level security; alter table public.notifications enable row level security; alter table public.reminders enable row level security; alter table public.administrators enable row level security; alter table public.audit_logs enable row level security;
create policy "public scholarship reads" on public.scholarships for select to authenticated using (true); create policy "public criteria reads" on public.eligibility_criteria for select to authenticated using (true); create policy "public requirement reads" on public.scholarship_requirements for select to authenticated using (true);
create policy "own profile" on public.profiles for all to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id); create policy "own saves" on public.saved_scholarships for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own applications" on public.applications for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own documents" on public.documents for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own notifications" on public.notifications for select to authenticated using ((select auth.uid())=user_id); create policy "own reminders" on public.reminders for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "own checklist through application" on public.application_checklist_items for all to authenticated using (exists(select 1 from public.applications a where a.id=application_id and a.user_id=(select auth.uid()))) with check (exists(select 1 from public.applications a where a.id=application_id and a.user_id=(select auth.uid())));
insert into storage.buckets (id,name,public) values ('documents','documents',false) on conflict do nothing;
create policy "private document upload" on storage.objects for insert to authenticated with check (bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid()::text)); create policy "private document read" on storage.objects for select to authenticated using (bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid()::text)); create policy "private document delete" on storage.objects for delete to authenticated using (bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid()::text));
